quests[37466] = { id = 37466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Academy" }
quests[37467] = { id = 37467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Walk of Shame", description = "The echoes of Nar'thalas still haunt me, and I cannot bear the pain of this accursed town any longer. I may still be able to get you closer to the Tidestone, however.\n\n<Farondis' eyes narrow in newfound determination.>\n\nWe will need to skirt around the edge of town. Follow me.", completion = "<The prince appears emotionally drained.>\n\nThis is the end of the road for me, {name}. I can't bear to look at them. Moreover, my mere presence puts you in danger.\n\nBeyond this point, you must walk alone.", objectives = "Escort Prince Farondis around the edge of Nar'thalas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37468] = { id = 37468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Academy", description = "The sunken structure on the other side of this bridge was once called Nar'thalas Academy: the center of magical studies in all of Azeroth. You should have seen her in her full splendor.\n\nThe Tidestone should be locked up within. I dare not enter, but you - my champion - you go with my blessing.", completion = "New student?", objectives = "Enter the halls of the Nar'thalas Academy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37469] = { id = 37469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tidestone: Shattered", description = "I suppose you can go in, then.\n\nThe shattered pieces of the Tidestone of Golganneth are contained within the academy's eastern wing. Even as curator, I cannot attest to their condition, as I have not been in to inspect them in many millennia.\n\nOh, young {name}? Please do not touch anything.", progress = "<The last remaining piece of the Tidestone lies before you.>", completion = "<You notice the reflection of something sinister upon the core's surface...>", objectives = "Collect the 5 Tidestone Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37470] = { id = 37470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Head of the Snake", description = "Those naga have the Tidestone shards, {name}. They will soon be dragging them into their watery holes, away from our reach.\n\nIt would be wise to take out their leaders before that happens.", progress = "I... I can't believe it...", completion = "You killed Athissa, {name}.\n\nThat is to say, you and... and my people...\n\nMy people... they fought for us...\n\nBut, Warlord Parjesh has escaped through the portal with the Tidestone. You must pursue him and retrieve the Pillar of Creation.", objectives = "Defeat Athissa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37471] = { id = 37471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dahrok Boneshatter" }
