quests[37474] = { id = 37474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basics First", description = "Great spirit, {name}, but you have to learn the basics of pet battles first.  Visit Audrey Burnhep in Stormwind City, and she'll get you started.", objectives = "Speak with Audrey Burnhep in Stormwind City.Great spirit, {name}, but you have to learn the basics of pet battles first. Visit Audrey Burnhep in Stormwind City, and she'll get you started.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37475] = { id = 37475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Molten Quarry" }
