quests[37483] = { id = 37483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captian's Whistle", progress = "We've brought our best here to help the fight for Ashran.\n\nBring me some of those Artifact Fragments and I'll give you a whistle to call a Captian to battle within the Road of Glory when you need them the most.", completion = "Good work. Use this whistle to call one of our very best to the battlefield when you need them the most.", objectives = "Bring Anne Dunworthy 100 Artifact Fragments for a Captian's Whistle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37484] = { id = 37484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Whistle", progress = "We've brought our best here to help the fight for Ashran.\n\nBring me some of those Artifact Fragments and I'll give you a whistle to call a Captian to battle within the Road of Glory when you need them the most.", completion = "Good work. Use this whistle to call one of our very best to the battlefield when you need them the most.", objectives = "Bring Anne Dunworthy 100 Artifact Fragments for a Captian's Whistle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37485] = { id = 37485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[37486] = { id = 37486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nar'thalas Still Suffers", description = "They have not forgiven me. I cannot blame them.\n\nPast crimes aside, I am still their prince. Even in death, I will do what I can to protect my people.\n\n{name}. Act as my champion. Find and defeat the creature that leads this naga attack against the people of Nar'thalas. After all these years, you - |5{race} {class}, of all things - may be the instrument of my redemption.", progress = "I will make it up to them. WE will make it up to them.", completion = "She spoke of the Tidestone? That sea witch must not realize how close she truly is to finding it.\n\nWe should move quickly. We are close to your prize, and the naga are circling in.", objectives = "Defeat Athissa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37492] = { id = 37492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rather Long Walk", description = "I'm concerned for Elder Aldryth. He went out for a walk about ten thousand years ago, and he has not returned.\n\nWith these naga attacking, I fear he may be in danger!\n\nIf you dare venture out into the fray, do look out for our court elder.", progress = "Have you seen him?", completion = "I can't tell you how relieved I am that Elder Aldryth has returned.\n\nHonestly, life here in the palace hasn't been the same without him. Everything seemed to have... lost its color. Perhaps now we can get back to our normal lives.", objectives = "Find Elder Aldryth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37493] = { id = 37493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Morphed Sentient" }
quests[37494] = { id = 37494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Cover of Darkness", description = "We are off to Stormwind. Tethys will sneak us by water beneath the old barracks under cover of darkness tonight.\n\nThe rest will be up to you, Mathias, and myself. We will have to stealth through Stormwind and confront Detheroc at SI:7.\n\nAre you ready to do this, {name}?", completion = "We made it. Now all we have to do is get up there, sneak through my city -- which, mind you, is being watched by everyone -- then reveal and kill a dreadlord inside the headquarters of SI:7, Azeroth's most elite spy organization.\n\nPiece of cake. Ready to save the world, {name}?", objectives = "Speak with Taoshi when you're ready for Fleet Admiral Tethys to arrange your transport to Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37495] = { id = 37495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder the Cove" }
quests[37496] = { id = 37496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Shipwreck Arena", description = "The giants at Shipwreck Arena are very fond of smashing ships that sail too close to shore. They take the sailors prisoner and use them for their own amusement.\n\nI suppose it will be easy for you to infiltrate the place. It's breaking out that will be the difficult part.", completion = "Did you get my bottle? Are you here to help us escape?", objectives = "Infiltrate Shipwreck Arena and find Okuna Longtusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37497] = { id = 37497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trailing the Tidestone", description = "Your quest for the Tidestone... it intrigues me. More than that, it suits my needs quite well. I have been in need of a champion for a very, very long time.\n\nIt is decided, then. I shall join you.\n\nWe will have to head east, through Nar'thalas.\n\nShall we depart?", completion = "Perhaps this was a mistake.", objectives = "Escort Prince Farondis to the Ruins of Nar'thalas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37501] = { id = 37501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Challenge Mode - Bronze Addition (1st)" }
quests[37502] = { id = 37502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Challenge Mode - Consolation (1st)" }
quests[37503] = { id = 37503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Challenge Mode - Gold Addition (1st)" }
quests[37504] = { id = 37504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Challenge Mode - Silver Addition (1st)" }
quests[37505] = { id = 37505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Draenor - Raid Finder - 1st" }
quests[37506] = { id = 37506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Draenor - Raid Finder - Nth" }
quests[37507] = { id = 37507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boss Whalebelly's in Charge", description = "Great, let's get started! If we're going to break everyone out of here, you need to pose as a pit fighter like the rest of us. They won't just let you run around anywhere you want in here.\n\nFirst thing you need to do is present yourself to Boss Whalebelly. The giants may run this place, but as far as posing as one of us, Whalebelly's in charge.\n\nHe's speaking with his goons just to the south.", progress = "Go on. Go talk to him.", completion = "That could have gone better. Sounds like you've already made an enemy.\n\nStill, that'll work to our advantage. You versus Boss Whalebelly. The fight of the century... or at least, the day.\n\nNow to set everything up.", objectives = "Speak with Boss Whalebelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37508] = { id = 37508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Stacking the Deck" }
quests[37509] = { id = 37509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Stacking the Deck" }
quests[37510] = { id = 37510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternfathom's Champion", description = "Since you defeated Ooker Dooker, there's a pit fighter spot open on Sternfathom's team. You should go establish yourself as his champion. That way, the giants won't think twice about why a stranger is suddenly coming and going as <he/she> pleases.\n\nMeanwhile, I'll start to sow some chaos so that we can strike at Prince Oceanus.", completion = "Hello, what can I do for you, little {race}?\n\nAhahaha... it's you!  I like how you came in and immediately confronted Whalebelly. That little tuskarr's got it coming.\n\nI can tell you're going to win big for me in the arena.", objectives = "Report to Sternfathom as his new pitfighter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37511] = { id = 37511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dizzy Sparkshift", description = "I'm in a pretty good spot as far as artifacts go.\n\nWe have a couple other society members out in the field. I'd go look for them, but it seems like a bad idea from a health perspective.\n\nYou don't seem to have a problem with pain, think you could find Dizzy?", completion = "Shh... keep it down. The last thing I want is to get punched in the face by an ogre.", objectives = "Find Dizzy Sparkshift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37512] = { id = 37512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primals Invasion! BETA", description = "The plants seem different today. Grass blades bend against the wind and catch on my boots. Twice this morning a tree branch struck my helmet as it fell.", objectives = "Repel the Primals invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37513] = { id = 37513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres Invasion! BETA", description = "Commander, our scouts say that Ogre bands march through the snow. If they want more battle after the beating we already delivered, then I'm eager to oblige them.", objectives = "Repel the Ogres invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37514] = { id = 37514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakers Invasion!! BETA", description = "The earth quakes beneath us, Commander. Our scouts are not returning. I can feel an attack creeping up on us, but from where?", objectives = "Repel the Goren and Gronnling invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37515] = { id = 37515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Horde Approaches... BETA", description = "There's smoke on the horizon... The Iron Horde is coming.", objectives = "Speak with Sergeant Crowler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37516] = { id = 37516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News for Nixxie", description = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation.\n\nIf you see her can you let her know we will be back soonish?", completion = "It sounds like the excavation of Broken Precipice is going to be fully operational in no time.\n\nI can't wait to line my pockets with some of that sweet moolah.", objectives = "Speak with Nixxie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37517] = { id = 37517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News for Nixxie", description = "Nixxie is probably worried sick about the potential loss of profits from this surveying operation.\n\nIf you see her can you let her know we will be back soonish?", completion = "It sounds like the excavation of Broken Precipice is going to be fully operational in no time.\n\nI can't wait to line my pockets with some of that sweet moolah.", objectives = "Speak with Nixxie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37518] = { id = 37518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Haunted Halls", description = "Now, what was it you wanted? You're here to see the Tidestone of Golganneth? Hah! Ho ho ha ha haa!\n\nHooo my.\n\nNo, only the academy's headmistress has the keys to that chamber, and she hasn't opened the door in... oh, I'd say about ten thousand years.\n\nYou'd best be off to class, now. Go on, then! Into the west wing with you!", completion = "Yes, the headmistress is in her study, but I can't have you bothering her right now. Classes are about to start.", objectives = "Enter the academy's west wing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37520] = { id = 37520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vileclaw's Claw", progress = "Vileclaw is feared throughout Nagrand as a vicious predator. While it is true that Vileclaw is one of the most dangerous raptors you'll ever encounter, she is also a savagely beautiful creature.\n\nVileclaw must be preserved for future generations to behold! If you can bring me back one of her vicious claws, I'll make sure you get a cut of the profit!", completion = "Nice work, {name}!\n\nIt's times like these that make me proud to be your mentor. You'll make a fine archaeologist someday!\n\nHere's your cut!" }
quests[37523] = { id = 37523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.", objectives = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37524] = { id = 37524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds be rousin' champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent dem from musterin' the forces dey be needin' to stand against us, and will help remind them that we are not an enemy they want to be makin'.", objectives = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37525] = { id = 37525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ak'ox the Slaughterer" }
quests[37526] = { id = 37526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farondis Murder Flag" }
quests[37528] = { id = 37528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Sleeping Giants Lie", description = "We're going to need a diversion to get close to Prince Oceanus. Are you thinking what I'm thinking?\n\nSee Sleepy Dhow over there? He's guarding all of the weapons the giants take from our shipwrecks. We can use those weapons to arm the rest of the pit fighters that are held in the caves.\n\nAll you have to do is get past that giant without waking him.", progress = "As soon as I can, I'll arm the gladiators in Oceanus Cove.", completion = "I couldn't have snuck past him better. Now, to get these weapons into the right hands.", objectives = "Collect the Giants' Stash of Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37530] = { id = 37530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Yourself", description = "Of course I couldn't sit back and let them just cart you away.\n\nI will explain everything.", progress = "Let me show you what happened.", completion = "What happened, Farondis?", objectives = "Speak with Farondis and hear his account of how he saved you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37531] = { id = 37531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking - See Closed Chest" }
quests[37536] = { id = 37536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morale Booster", description = "Things may look good from where you're standing, but, we're losing. However, do not fret, my little {race} friend. You can help.\n\nListen closely. Ooka Dooker, Ooker's sister, is back over yonder in the champions' cave making her world famous Fighter Chow. It'll do the trick and boost our team's morale.\n\nAll you have to do is to convince her to hand it over.", completion = "Yes, this'll do nicely... oh no! The last of my pit fighters have been defeated.\n\nIt's just you and me now, little {race}.", objectives = "Get the Fighter Chow from Ooka Dooker", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37537] = { id = 37537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravyn-Drath" }
quests[37538] = { id = 37538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 1, Fight!", description = "All of my gladiators are out of commission!\n\nIt's down to you, {name}. Bilgerudder's going to pit his three champions against you.", completion = "<This is where you expected to find Okuna. Instead, you only found the pack with the weapons.>", objectives = "Have Sternfathom throw you into the arena, defeat Boss Whalebelly, and then find Okuna Longtusk inside Oceanus Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37540] = { id = 37540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of the Iron Conqueror", description = "Redeem your Essence of the Iron Conqueror with Lady Liadrin to select an armament of your choice.", progress = "Well met, {class}. I see you have a claimed a trophy in your recent battles.", completion = "{name}, your courage and dedication has made Draenor a safer place. Take these armaments and go in the Light.", objectives = "Collect an Essence of the Iron Conqueror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37541] = { id = 37541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of the Iron Vanquisher", description = "Redeem your Essence of the Iron Vanquisher with Lady Liadrin to select an armament of your choice.", progress = "Well met, {class}. I see you have a claimed a trophy in your recent battles.", completion = "{name}, your courage and dedication has made Draenor a safer place. Take these armaments and go in the Light.", objectives = "Obtain an Essence of the Iron Vanquisher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37542] = { id = 37542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time for Tryouts", description = "We don't have time for you to go through a lengthy set of tryouts. But, fighting in the arena is our best chance at getting you in good with the giants.\n\nThat kind-hearted giant over there that's losing against Bilgerudder is Sternfathom. If you were to defeat his hozen champion, you'd make yourself a spot on his team.\n\nLooks like Ooker Dooker's taking a rest between bouts. Now's the time to deliver a good ol' monkey beatdown.", progress = "By giving that hozen a good beating, you'll be making a spot for yourself in the arena.\n\nYou don't have to kill him, though.", completion = "You made quick work of that monkey. Now there's an empty position on Sternfathom's team that you can fill.\n\nBut first, let's get me set up for what comes after your big match.", objectives = "Deliver a beatdown to Ooker Dooker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
