quests[37652] = { id = 37652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Jabberjaw" }
quests[37653] = { id = 37653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Souls", description = "I need to extract information about the Burning Legion from these foul creatures. But living, the demons are almost impossible to break.\n\nHowever, like you, I wield a powerful artifact -- the Scythe of Souls.\n\nTake one of my soul gems. If you place it next to a demon's corpse, it will rip the 'soul' out. Then, we will see if the scythe can get them to talk.", progress = "We need those demon souls, {name}.", completion = "Yes. Already, I can tell their souls are weaker than their flesh.", objectives = "Trap 8 demon souls on the Faronaar Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37654] = { id = 37654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maritime Law", description = "Good <sir/madame>, a moment of your time. My fellow salvors and I could not help but notice yon ship that ran aground in the storm last night.\n\nA pity about its crew.\n\n<Mr. Shackles makes empathetic gestures.>\n\nStill, the law's the law. The maritime code is quite clear on the matter. If you find yourself out that way, would you mind terribly checking in on my acquisitions scout, Looper? I would have expected him back for tea some time ago.", completion = "Do you know what ship this is? It's the Queen's Reprisal. Queen... as in the Banshee Queen, Sylvanas Windrunner.\n\nIf the farmstead weren't sunk under the waves, I'd be heading home to Gilneas right about now.", objectives = "Find Looper Allen near the ship that's run aground on the east side of Mak'rana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37656] = { id = 37656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Machinations", description = "My force wiped out the demons' forward base here. But, an imp mother and her brood took the rest of my demon hunters hostage, including Cyana Nightglaive.\n\nWe need to free the Illidari and destroy the Burning Legion.", progress = "If we're to defeat the Legion, we need to know exactly what they're up to.", completion = "I've always had my doubts about Cyana. Something was never quite right there. Looks like she cracked and joined the Legion.\n\nStill, we are not going to let her, or this Cordana Felsong, get away with it.", objectives = "Free 6 Demon Hunters from Soul Harvesters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37657] = { id = 37657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the World Safe for Profit", description = "Might I ask a small favor, my friend? These creatures in the tide pools to the east are starting to frighten me. Our efforts to trade with them have been rebuffed at every turn with aggression. This is not good; neither for running a business, nor for profit.\n\nSadly, I must admit the time for talk has come to an end.\n\nMight you be willing to serve as my representative in dealing with the denizens of Mak'rura and their \"queen\"?\n\nI can assure you that your efforts will be rewarded commensurately.", progress = "How goes the cleanup?", completion = "What? A jailer demon you say? Oublion? What a ghastly name.\n\nNo wonder we couldn't become trade partners with them. Oh, if only I'd known, there wouldn't have been any need for such slaughter!\n\nAh well. Live and learn.", objectives = "Kill 12 gilblin and/or makrura at Mak'rana and slay their leader, Queen Kraklaa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37658] = { id = 37658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reignite the Wards", description = "The demons are weakening my defenses. They must be far more powerful than what we've faced before.\n\nWill you help me to reignite the wards to keep the Legion from overrunning our position here?", progress = "All of the wards need to be reignited if we're to hold the front.", completion = "Thank you, {name}. That will give us the breathing room we need to launch our counter-offensive.", objectives = "Reignite the 3 demon wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37659] = { id = 37659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Foot Locker", description = "I don't care what you do, mate. But, if you get caught, you didn't see me.\n\nI wasn't here.", completion = "<Amongst the moldering remains of the chest, you find the captain's log. Its pages are partially intact and it contains interesting information about the possible whereabouts of Queen Sylvanas Windrunner, the new warchief of the Horde.>", objectives = "Locate the Captain's Chest below decks on the Queen's Reprisal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37660] = { id = 37660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scythe of Souls", description = "Let's head to the other side of the stand. We will release the demon souls one by one and get the answers that we seek concerning Lord Illidan.\n\nThe Scythe of Souls will ensure that we do.", progress = "We need to compel the demons, {name}.", completion = "I wouldn't take what Arev'naal said to heart. The inquisitor demons are masters of misinformation. You don't suspect betrayal within the ranks, do you?\n\n<The Souleater looks thoughtful and grim.>\n\nI fear we won't have all of our answers about Lord Illidan for a while.", objectives = "Work with Allari the Souleater to compel information from the demon souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37666] = { id = 37666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking a Fight", description = "They're coming, {name}!\n\nI will get to work unlocking these fel-magic chains from the cage.\n\nYou keep the Legion at bay.", completion = "You have my eternal gratitude, {name}. Let it never be said that I have underestimated the reach and prowess of the Uncrowned.\n\nThe easy part's done. Now it's time to do the impossible.", objectives = "Kill demons until Vaultwarden Umbral appears and kill him. Then, set Mathias Shaw free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37667] = { id = 37667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building for Professions", description = "I see that you have acquired the blueprints for a profession building! Use the Architect Table to build in a small plot.", objectives = "Build any profession building.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37669] = { id = 37669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building for Professions", description = "I see that you have acquired the blueprints for a profession building! Use the Architect Table to build in a small plot.", progress = "How is it coming along?", completion = "Congratulations!", objectives = "Build any profession building.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
