quests[37678] = { id = 37678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hit the Books", description = "<The librarian speaks in shushed tones.>\n\nOne problem with maintaining such a large arcane library is that the books often pick up an errant enchantment and start darting about on their own. These overmagicked books need to be destroyed before they cause any further damage.\n\nIf you encounter any of these exasperating essays, please put them down. Quietly.", progress = "<The librarian sighs quietly.>", completion = "Don't worry about the scattered pages and spines - I will have my aides clean up.\n\nThank you. You may return to your studies.", objectives = "Destroy 3 Ancient Tomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37681] = { id = 37681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
