quests[37684] = { id = 37684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[37687] = { id = 37687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: In the Shadows", description = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that?\n\n<Reshad's voice drops to a whisper>\n\nThere is movement in the shadows, we are being watched!\n\nTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", completion = "So the Shadow Council is involved? Interesting...", objectives = "Kill 3 Council Nightblades within Lion's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37688] = { id = 37688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: In the Shadows", description = "I need your help. Iskar has gone missing. I have reason to believe he has followed the remnants of the Sethekk who have been gathering here in Tanaan. I've been investigating and... what was that?\n\n<Reshad's voice drops to a whisper>\n\nThere is movement in the shadows, we are being watched!\n\nTake these vials, they form a gas with a terrible smell when the liquid comes in contact with the air. Smells terrible, they won't be able to resist it. Use them to drive our watchers out of hiding.", progress = "Did you take care of our watchers?", completion = "So the Shadow Council is involved? Interesting...", objectives = "Kill 3 Council Nightblades within Vol'mar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37689] = { id = 37689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Imposter", description = "Detheroc has SI:7's finest snipers on all of the rooftops. We can't mount up and we can't fly. There are grapple points above so that we can move up the cliff. \n\nWe've also setup hay bales to hide in along the likely routes to SI:7. We just need to stealth in and kill Detheroc.\n\nOnce we get up there, we'll separate to increase the chances of at least one of us making it through the city.\n\nGood luck, {name}.", completion = "You did it! Mathias Shaw is back in charge of SI:7 and you prevented an all-out war between the Alliance and Horde.\n\nThe rest of us agree, you've proven yourself an invaluable member of the Council of Shadows and the Uncrowned.\n\nCongratulations, Shadowblade {name}!", objectives = "Grapple up the Lion's Rest cliffs, sneak through Stormwind City to the SI:7 courtyard, and then kill Detheroc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37690] = { id = 37690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Who Remember", description = "The ghostly elves, to the south, once had the Pillar of Creation known as the Tidestone of Golganneth.\n\nTheir great city of Nar'thalas was destroyed an eon ago. The city's ruler, Prince Farondis, fell with the city. You small ones die so easily.\n\nIf anyone knows where the fragments rest, it will be the ghost of the prince. Seek out his people.", completion = "Who goes there?\n\nAre you an emissary from that bizarre floating city?", objectives = "Locate Nightwatcher Idri in the Drowned Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37691] = { id = 37691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "he Ancient One", description = "This place is now the home of what is left of the Blue Dragonflight. Its eldest dragon, Senegos, lies ahead within a pool of ley energy. If any are wise enough to help us find the Pillar of Creation that we seek on Azsuna, it will be him.\n\nStellagosa went ahead to join her grandfather. She assured me that we are welcome to enter the repose.\n\nCome, {name}, we must hurry. Even from here, I can sense his life force waning. Let us approach him together.", objectives = "Approach Senegos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37697] = { id = 37697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Goblin" }
quests[37713] = { id = 37713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 002 - El'dranil Tablet" }
quests[37726] = { id = 37726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valiyaka the Stormbringer" }
quests[37727] = { id = 37727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magister of Mixology", description = "As you must know, I'm a connoisseur of drinks... specifically, arcane-infused spirits. Cocktail mixing is alchemy, and as everyone knows, alchemy is magic.\n\nMy latest drink must be more exotic than anything I've conjured before. I already have most of what I need. But there are a couple of items left on the list.\n\nNotice the herons down in the lagoon? As with many of the creatures on Azsuna, the magic coursing through the island permeates them.\n\nTheir eggs will do nicely.", progress = "Are we speaking again because you have my eggs?", completion = "Capital! A prodigious start.\n\nI implore you to create this marvelous mixture for yourself. I want to share the delight of alchemical spirits with the world!\n\nYou'll need to get more eggs for yourself, though.", objectives = "Collect 6 Arcane-Infused Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37728] = { id = 37728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Presentation is Everything", description = "The eggs will provide the 'oomph' to my drink's character. But there's another element, and this must not be underestimated!\n\nPresentation.\n\nNow, you could go with your standard olive skewered on a toothpick. Maybe a carrot stalk stuck slapdash out of a glass.\n\nBut then, you wouldn't be me.\n\nNo, my friend. What MY drink needs to sell it visually comes from a one-of-a-kind creature. I'm only going to serve it once and so my drink deserves something unique.\n\nThe eyes of Gangamesh are what I need.", progress = "Yes? You have the eyes?", completion = "I was going to present this to one of the ladies of the court. Doing so might increase my standing in certain social circles.\n\nBut, I just can't bring myself to do it. Who better to drink my latest masterpiece than, well... me?", objectives = "Collect the Six Eyes of Gangamesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37729] = { id = 37729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pop Quiz: Advanced Rune Drawing", description = "Still aching to get into the headmistress' study, eh? I suppose I can let you in... as long as you prove that you've been studying.\n\nProper rune formation is essential when it comes to spellcasting. If you can draw a rune, you can cast a spell.\n\nI will provide outlines for you. You can simply use your feet to trace the runes.", progress = "Go on, then! Get those feet moving!", completion = "Exemplary work, young {name}. With runes like these, you'll be graduating in no time.", objectives = "Trace an arcane rune, a fire rune, and a frost rune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37730] = { id = 37730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headmistress' Keys", description = "I have a suspicion you are avoiding your studies - but I can see you're anxious to see the Headmistress.\n\nVery well! Headmistress Azuremoon can be found up ahead, though I doubt she will enjoy being interrupted.", progress = "Were you able to meet with the headmistress?", completion = "She... she gave you her key? My word!", objectives = "Obtain the Tidestone Vault Key from Elya Azuremoon, the Academy Headmistress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37733] = { id = 37733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prince Farondis", description = "I'm glad to see that my doubts in you were unfounded.\n\nYou seek Prince Farondis? Follow me. I will show you to the prince's hall.", completion = "That's him, behind me.", objectives = "Meet up with Nightwatcher Idri at the Crumbled Palace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37736] = { id = 37736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing With Class", description = "Now stop right there. Look at you! You look like you just walked in off of the street. Where are your robes and hat?\n\nAnd don't tell me you've entered the academy without your wand and spellbook.\n\nFreshmen.\n\nPut yourself together, and maybe then I will consider letting you enter the academy.", progress = "Still trying to get into the academy, I see.", completion = "Your hat and robes don't match, but you still look better. I hardly recognize you.", objectives = "Obtain a Nar'thalas Academy Hat, Robes, Wand, and Spellbook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37749] = { id = 37749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trials of Khadgar: Iron Maidens", description = "Defeat your enemies with greater skill to earn the favor of Khadgar - and with it, greater rewards!", objectives = "Defeat the Iron Maidens encounter, with the following conditions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37750] = { id = 37750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions Active" }
quests[37751] = { id = 37751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounties Active" }
quests[37752] = { id = 37752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battles Active" }
quests[37753] = { id = 37753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Hunter Active" }
quests[37754] = { id = 37754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungeon Active" }
quests[37756] = { id = 37756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walled City: Brackenspore", description = "The Iron Horde is just one of the threats we must deal with on Draenor. We must also clean up the chaos they are leaving in their wake.\n\nBrackenspore, ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. He spreads his fungal growth in his wake and will eradicate all of us if left unchecked.\n\nTravel to Highmaul and defeat Brackenspore.", completion = "Very good, Commander! Brackenspore's infestation will not be spreadin' to da rest of Draenor.", objectives = "Defeat Brackenspore in Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37757] = { id = 37757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Sanctum: Ko'ragh", description = "Forget all you know of the ogres on Azeroth, {name}. On Draenor they commanded a once-mighty civilization. Even now they threaten to reclaim their former glory.\n\nHighmaul excavations in Nagrand unearthed a mysterious relic. The only ogre to survive direct exposure to this relic was Ko'ragh; he was left with a near-complete immunity to all magic.\n\nKo'ragh must be killed before the ogres learn to replicate his unique powers. Travel to Highmaul and defeat Ko'ragh!", completion = "Ko'ragh be defeated. You be as strong as dey say, commander. I be proud to be at your side.", objectives = "Defeat Ko'ragh in Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37758] = { id = 37758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperator's Rise: Imperator Mar'gok", description = "The conditions are ripe for a decisive attack against the Highmaul, commander. Will you engage?\n\nDescended from a long line of sorcerers, Imperator Mar'gok is the grand Imperator of Highmaul. He is both cunning and brutal, and allied himself with the Iron Horde when he recognized what it would be to oppose them.\n\nTravel to Highmaul and defeat Imperator Mar'gok. Without their leader, the Ogre Empire will descend into chaos for many years.", completion = "A brilliant victory, commander! Imperator Mar'gok be defeated. You indeed be a champion of da Horde!", objectives = "Defeat Imperator Mar'gok in Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37762] = { id = 37762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slagworks: Heart of the Mountain", description = "Blackrock orcs fight like no other clan. They rely on arms and armor forged in the heart of their unnatural crucibles.\n\nDeep within the Foundry of the Blackrock clan is a furnace powered by a primal force known as the Heart of the Mountain. Destroy it, and deprive our foe of the arms they rely on.\n\nTravel to Blackrock Foundry and defeat the Heart of the Mountain.", completion = "Well done, commander. With da Heart of da Mountain defeated, you have crippled the ability of da Blackrock clan to use their most powerful furnace.", objectives = "Defeat the Heart of the Mountain at the Blast Furnace in Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37763] = { id = 37763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Forge: Kromog", description = "Commander. Frostwolf scouts report that blackrock miners dug up a magnaron, and they've coerced the beast into helping them to create their infernal machines. They call it \"Kromog.\"\n\nWe must destroy it, {name}. Travel to Blackrock Foundry and defeat Kromog.", progress = "Da defeat of Kromog will hinder da Iron Horde's operations within da Foundry.", completion = "Well done, commander! Not since Garrosh Hellscream commanded our forces in Northrend have I seen such decisive action.", objectives = "Defeat Kromog in Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37764] = { id = 37764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Assembly: Admiral Gar'an", description = "Our forces are making progress on land, but victory at sea still eludes us. We must take out the Iron Horde leadership while they are in harbor.\n\nGar'an, Admiral of the Iron Horde fleet and first of the so-called Iron Maidens, is tactically brilliant. She, along with her lieutenants, Marak, and Sorka, have crushed all who have been sent to oppose them.\n\nTravel to Blackrock Foundry and defeat Admiral Gar'an.", completion = "Brilliant work, commander. Without da mind of Admiral Gar'an behind it, da Iron Horde's naval fleet be greatly diminished.", objectives = "Defeat Admiral Gar'an in Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37765] = { id = 37765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackhand's Crucible: Blackhand", description = "Grommash Hellscream relied on the strength of his Warlords to keep the Iron Horde under his control. It is time to strike a decisive blow.\n\nBlackhand, Warlord of the Blackrock clan, is a dauntless warrior and ruthless tyrant. He is second only to Grommash within the Iron Horde and oversees operations in the Foundry from atop its Crucible.\n\nTravel to the Blackrock Foundry and defeat Blackhand.", completion = "One of da most ruthless orcs to walk any land be defeated. You be havin' my congratulations, and my thanks.", objectives = "Defeat Blackhand in the Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37766] = { id = 37766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walled City: Brackenspore", description = "If it ain't one threat, it's another - I swear this light-forsaken world would try to eat us alive even without no Horde to fight.\n\nBrackenspore, ancient walker of the deep, was drawn from the waters near Highmaul by the presence of the Iron Horde. That thing is already spreading like a disease, {name}. Ye got to put it down!\n\nTravel to Highmaul and defeat Brackenspore before he gets too powerful to stop.", completion = "Excellent! Brackenspore's infestation will not spread to the rest of Draenor. Thank you, commander.", objectives = "Defeat Brackenspore in Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37767] = { id = 37767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Sanctum: Ko'ragh", description = "Ye know the name \"Ko'ragh?\" One of them Highmaul ogres. They dug up a relic some time ago that killed everyone it touched but for Ko'ragh... givin' him a near-complete immunity to all magic.\n\nOgres ain't meant to have that kind of power! Travel to Highmaul and defeat Ko'ragh, before they learn to use him against us.", progress = "Why would Ko'ragh remain a lackey to the sorcerer king despite his unique gifts? Ogres.", completion = "Great work! Ko'ragh is defeated. You truly are as powerful as they say.", objectives = "Defeat Ko'ragh in Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37768] = { id = 37768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperator's Rise: Imperator Mar'gok", description = "I never thought much of them ogres, not until I saw a Highmaul legion on the march. Like a wall o' armored muscle, backed by the magics o' the emperor's best sorcerers. Never underestimate an ogre.\n\nImperator Mar'gok is the grand Imperator of Highmaul. Aye, he's a cunning one - allied himself with the Iron Horde, he did. If we're to break up the party, we'd best start at the top.\n\nTravel to Highmaul and defeat Imperator Mar'gok!", completion = "Well done! A great blow has been dealt this day.", objectives = "Defeat Imperator Mar'gok in Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37769] = { id = 37769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slagworks: Heart of the Mountain", description = "Blackrock warriors use weapons forged in cursed fire by the breath of a creature o' pure flame: The Heart o' the Mountain. Let's disarm 'em, <boy/lass>! Destroy that infernal creature, and the Blackrock won't have enough heat to fuel their Blast Furnace.\n\nTravel to Blackrock Foundry and defeat the Heart o' the Mountain.", completion = "Well done, commander! With the Heart of the Mountain defeated, the Blackrock will have nothing to wield but sticks and stones.", objectives = "Defeat the Heart of the Mountain at the Blast Furnace in Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37770] = { id = 37770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Forge: Kromog", description = "Yer garrison scouts report that blackrock miners dug up a magnaron, and that the filthy beast has begun helpin' those brutes churn out their infernal machines. They call it \"Kromog.\"\n\nTravel to Blackrock Foundry and slay that fiend!", completion = "With Kromog defeated, we won't seeing as many Iron Horde machines rolling out to the front lines. You've saved a lot of lives today, commander.", objectives = "Defeat Kromog in Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37771] = { id = 37771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Assembly: Admiral Gar'an", description = "\"If ye want to topple a wall, start with the foundation.\" It's an old Dwarf saying. If we take out the Iron Horde's leadership, the whole thing tumbles.\n\nGar'an is the Admiral o' the Iron Horde fleet and first of the so-called \"Iron Maidens.\" She, along with her lieutenants, Marak, and Sorka, have dominated the seas of Draenor.\n\nNo more, {name}. Travel to Blackrock Foundry and defeat Admiral Gar'an.", completion = "Great work, commander! We'll wrest control of the seas yet!", objectives = "Defeat Admiral Gar'an in Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37772] = { id = 37772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackhand's Crucible: Blackhand", description = "Ol' Grommash cannot rule the Iron Horde without his Warlords keeping the clans in line. Let's deal 'em a blow that they can't recover from! Blackhand, Warlord of the Blackrock clan, is a dauntless warrior and ruthless tyrant. He's second only to Grommash within the Iron Horde and oversees operations in the Foundry from atop its Crucible.\n\nTravel to the Blackrock Foundry and defeat Blackhand.", completion = "So it's done, then? The foundry is in shambles. We've delivered a mighty blow today, commander. Great work!", objectives = "Defeat Blackhand in the Blackrock Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37773] = { id = 37773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Amethon!", description = "Foreman Eksos down in your Talador outpost figures he has the answer for why there's been so much seismic activity recently.\n\nSee, there's this giant, ah... earth fury, I think they're called, and it's covered in these powerful crystals in a cave up above Kuuro's Claim. The crystals hum real loud and we think it's driving the fury crazy!\n\nProblem is, nobody's got the firepower to take the thing down so we can examine a sample. Think you could lend us a hand, commander?", progress = "Sir, what is that you have there?", completion = "Excellent, this must be the crystal Eksos keeps talking about. We'll get top men studying this right away.", objectives = "Retrieve a Humming Draenite Spike from Amethon above Kuuro's Claim in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37774] = { id = 37774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Gor'thul!", description = "Saberon spirit army. I ain't pullin' your leg, commander, that's what we've got coming for us if we don't act fast.\n\nThe Shattered Hand shaman Gor'thul was spotted down in Spires of Arak in the Bloodmane Pridelands right about the same time we started hearing reports of saberon spirits raiding our supply caravans.\n\nI don't want to take any chances, commander. I think you should personally head down there and put a stop to this before it starts.", completion = "Perfect, sir. I'm glad we won't have to worry about saberon spirits on top of everything else that's trying to murder us.", objectives = "Slay Gor'thul at Bloodmane Pridelands in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37775] = { id = 37775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Nullifier Darkoor!", description = "You ever heard of the Ring of Blood, commander?\n\nIt's pretty simple. Big ogre named Mogor loves watching people fight for their lives against savage beasts. Ambitious goblin called Gurgthock arranges the fights and rakes in the profits.\n\nAnwyays, Gurgthock and I are long time buddies and he's arranged a special exhibition match just for you! Pretty sweet, right? Just whisper into his ear \"I seek the seeker.\"", completion = "Word is already spreading of your epic fight, commander. This may improve relations with the ogres in the future.", objectives = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37776] = { id = 37776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Undertow!", description = "Good day to ya, commander!\n\nI have bad news.\n\nWe've been contracting out some spy work to the local fisherman - we pay 'em some coin, they take their boats out north of Umbrafen and see what the Iron Horde's up to. Win-win, right?\n\nWell, it turns out... no. Every boat that goes out never comes back. Apparently this giant water elemental, Undertow I think it was, is murdering the snot out of everyone that passes through.\n\nAny chance you could clear it out for us, commander?", completion = "Thank you, commander. We hope the intel we gather from the Tanaan Channel will prove very useful in the coming months.", objectives = "Kill Undertow in the Tanaan Channel north of Umbrafen in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37777] = { id = 37777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Tremor!", description = "Your outpost in Gorgrond has a serious saberon problem, commander, and we can't really afford to keep sending more troops to help 'em out. So I have an idea.\n\nThere's an enormous worm beast on the west coast of Gorgrond called Tremor, better known as the devourer of lobstroks. If you took that thing down and brought the, well, pile of partially digested lobstrok meat back here, we can cook it here, ship it back there, use it to calm the saberon for a good long time!", progress = "Orders commander?\n\nAnd what is that awful smell?!", completion = "Excellent. This meat ought to keep those pesky saberon busy.", objectives = "Kill Tremor west of Gorgorek's Fall in Gorgrond and obtain the Pile of Partially Digested Lobstrok Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37778] = { id = 37778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Hivelord Ik'rix!", description = "We've got a radical new idea to try using ice ravager carapaces in our tempering process for armor and weapons. It's the sort of trailblazing work we strive for, commander!\n\nOnly problem is, ravagers apparently aren't keen on our guys and gals taking their carapaces off of them. There's this particular ravager at the Southwind Cliffs in Frostfire Ridge called Hivelord Ik'rix - if you could take him down we wouldn't need more for weeks!", progress = "Yes, commander?", completion = "Thank you, commander. We will get to work on this right away!", objectives = "Retrieve the Iceshatter Carapace from Hivelord Ik'rix at Southwind Cliffs in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37779] = { id = 37779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tip the Scales" }
quests[37780] = { id = 37780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun", description = "Commander, Gul'dan's favored agent Teron'gor has infiltrated Auchindoun in Talador and has already taken to devouring the countless souls within. We must not let this nefarious warlock gain any further strength.\n\nEnter the holy mausoleum of Auchindoun and rout Teron'gor and the rest of the Shadow Council before more damage is done.", completion = "Another agent of Gul'dan be fallin' before your might, commander. Gul'dan will surely be tremblin' at the heels of our victory dis day.", objectives = "Defeat Teron'gor in Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37781] = { id = 37781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodmaul Slag Mines", description = "The Bloodmaul ogres are brutal slavers, commander. Innocents from across Draenor are dragged deep into the volcanic slag mines in Frostfire Ridge to dredge up cart after cart of gems and ore, never to return.\n\nWe suspect that they have turned their focus to unearthing an ancient relic of immense power for their sorcerer-king.\n\nThe ogre Gug'rokk rules over the slag mines with an iron fist. Take him down and the mines will fall as well.", progress = "We can't allow da slag mines to operate. Gug'rokk has cracked his last whip against da bloody backs of the innocent.", completion = "Da Bloodmaul be finished, and with dem Imperator Mar'gok's chances of acquirin' da relic within da slag mines.\n\nDs be a good day, mon.", objectives = "Defeat Gug'rokk in the Bloodmaul Slag Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37782] = { id = 37782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimrail Depot", description = "We must move quickly, commander. As we speak the Grimrail is preparing to depart Grimrail Depot to deliver a massive battalion of troops to Shattrath. Rumor has it that they have outfitted the train with a weapon strong enough to shatter the shield protecting the inner city.\n\nSkylord Tovra has taken to guarding the train on its journey to Talador. You must stop Tovra and the Grimrail before it reaches Shattrath!", completion = "Derailing da Grimrail be a mighty blow to da Iron Horde. It will take dem a great deal of time to amass more troops thanks to you.", objectives = "Defeat Skylord Tovra in Grimrail Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37783] = { id = 37783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Docks", description = "The Iron Docks is one of the Iron Horde's greatest assets in this war. Our scouts have reported that the docks are alight with activity, indicating imminent attack.\n\nSkulloc, son of Gruul, was seen leaving the Blackrock Foundry, armed to the teeth with powerful cannons, and has been loaded onto their mightiest warship. It does not matter where they intend to strike, commander - you must sack the Iron Docks and defeat Skulloc before they ever leave.", completion = "Without Skulloc and their precious docks, da Iron Horde be a wolf pack trapped within their own cave... unable to hunt.", objectives = "Defeat Skulloc in the Iron Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37784] = { id = 37784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Burial Grounds", description = "Ner'zhul was once a noble orc - he was the wise chieftain and elder shaman of the Shadowmoon clan. In his desperate bid to join the Iron Horde he has spat on all he once stood for and twisted his ancestors' spirits to tap into dark, forbidden power... all to please Hellscream.\n\nThe Shadowmoon has fallen, commander. Enter their ancestral burial grounds and put an end to Ner'zhul's madness before he pulls all of Draenor into the engulfing maw of the void.", completion = "I already be feelin' da relief of da ancestral spirits of Draenor with Ner'zhul's fall. You have deprived Grommash of a powerful weapon, commander.", objectives = "Defeat Ner'zhul in the Shadowmoon Burial Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37785] = { id = 37785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skyreach", description = "High Sage Viryx has finished a devastating crystal superweapon atop the highest point in Skyreach in Spires of Arak. She intends to eradicate the 'lesser races' in the name of their god Rukhmar.\n\nThe arakkoa outcasts were nearly wiped out in mere seconds by the weapon. You must stop Viryx before she turns her sights to your garrison, commander.", completion = "Perhaps now da Adherents of Rukhmar will respect we 'lesser races'.", objectives = "Defeat High Sage Viryx in Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37786] = { id = 37786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Everbloom", description = "The Kirin Tor created an outpost in Gorgrond with a portal to Stormwind to facilitate quick reinforcements in the assault on the Blackrock Foundry. In their infinite wisdom they built it in the heart of the Everbloom, home to the botani and the mightiest of the genesaur - Yalnu.\n\nThe outpost has already been overrun and it is only a matter of time before the overgrowth spreads to Stormwind... and with it the whole of Azeroth.", completion = "Dese wizards' deaths be punishment enough for their lack of foresight. We should be thankful dat we were able to stop da overgrowth before it reached our world.", objectives = "Defeat Yalnu in the Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37787] = { id = 37787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upper Blackrock Spire", description = "Hellscream's Ironmarch vanguard managed to reach Blackrock Mountain and has allied with Warlord Zaela of the Dragonmaw clan. Even now the Iron Horde readies to invade Azeroth while Zaela prepares a doomsday weapon in the heart of the mountain to ensure nothing stands in their way.\n\nYou must put a stop to Zaela once and for all, commander. She has been a thorn in our side for too long.", completion = "With Warlord Zaela's fall we can be focusin' our efforts on Draenor and da heart of da Iron Horde. They have nowhere to hide now.", objectives = "Defeat Warlord Zaela in Upper Blackrock Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37788] = { id = 37788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Contract: Gutrek's Cleaver", description = "In Nagrand, the ogres tell of an ancient weapon called Gutrek's cleaver. I would very much like to study it.\n\nA goblin treasure hunter by the name of Val Goldspade discovered the whereabouts of the weapon. Unfortunately, this goblin has gone missing somewhere in the Broken Precipice - probably after a run-in with the locals.", objectives = "Search the ogres in the Broken Precipice for clues regarding Goldspade's discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37789] = { id = 37789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upper Blackrock Spire", description = "Hellscream's Ironmarch vanguard managed to reach Blackrock Mountain and has allied with Warlord Zaela o' the Dragonmaw clan. Even now the Iron Horde readies to invade Azeroth while Zaela prepares a doomsday weapon in the heart o' the mountain to ensure nothing stands in their way.\n\nYou must put a stop to Zaela once and for all, commander. She's been a thorn in our side for too long.", completion = "With Warlord Zaela out of the picture we can focus our efforts on Draenor and the heart of the Iron Horde. They have nowhere to hide now.", objectives = "Defeat Warlord Zaela in Upper Blackrock Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37790] = { id = 37790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Everbloom", description = "The Kirin Tor created an outpost in Gorgrond with a portal to Stormwind to facilitate quick reinforcements in the assault on the Blackrock Foundry. Unfortunately they built it in the heart o' the Everbloom, home to the botani and the mightiest o' the genesaur - Yalnu.\n\nThe outpost has already been overrun and it is only a matter o' time before the overgrowth spreads to Stormwind... and with it the whole of Azeroth.", completion = "I wish we could have saved the mages' lives, but sadly it was not to be. We should be thankful that we were able to stop the overgrowth before it reached our world.", objectives = "Defeat Yalnu in the Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37791] = { id = 37791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skyreach", description = "High Sage Viryx has finished a devastatin' crystal superweapon atop the highest point in Skyreach in Spires of Arak. She intends to eradicate the 'lesser races' in the name of their god Rukhmar.\n\nThe arakkoa outcasts were nearly wiped out in mere seconds by the weapon. You must stop Viryx before she turns her sights to your garrison!", completion = "Perhaps now the Adherents of Rukhmar will respect we 'lesser races'.", objectives = "Defeat High Sage Viryx in Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37792] = { id = 37792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Burial Grounds", description = "Ner'zhul wasn't always evil - once he was the wise chieftain and elder shaman o' the Shadowmoon clan. In his desperate bid to join the Iron Horde he's forsaken all he once stood for and twisted his ancestors' spirits to tap into dark, forbidden power... all to please Hellscream.\n\nEnter their ancestral burial grounds and put an end to Ner'zhul's madness before he pulls all o' Draenor into the engulfing maw o' the void.", completion = "I'm no shaman--far from it--but even I can feel the relief of the ancestral spirits of Draenor with Ner'zhul's fall. You have deprived Grommash of a powerful weapon, commander.", objectives = "Defeat Ner'zhul in the Shadowmoon Burial Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37793] = { id = 37793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Docks", description = "The Iron Docks is one o' the Iron Horde's greatest assets in this war. Our scouts have reported that the docks are alight with activity, indicatin' imminent attack.\n\nSkulloc, son o' Gruul, was seen leavin' the Blackrock Foundry, armed to the teeth with powerful cannons, and has been loaded onto their mightiest warship. It doesn't matter where they intend to strike, commander - you must sack the Iron Docks and defeat Skulloc before they ever leave!", completion = "Without Skulloc and their precious docks, the Iron Horde won't be launching any attacks for a good long time!", objectives = "Defeat Skulloc in the Iron Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37794] = { id = 37794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimrail Depot", description = "We must move quickly, commander. As we speak the Grimrail is preparing to depart Grimrail Depot to deliver a massive battalion o' troops to Shattrath. Rumor has it that they have outfitted the train with a weapon strong enough to shatter the shield protectin' the inner city.\n\nSkylord Tovra has taken to guardin' the train on its journey to Talador. You must stop Tovra and the Grimrail before it reaches Shattrath!", completion = "Derailing the Grimrail is a mighty blow to the Iron Horde. It will take them a great deal of time to amass more troops thanks to you.", objectives = "Defeat Skylord Tovra in Grimrail Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37795] = { id = 37795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodmaul Slag Mines", description = "The Bloodmaul ogres are brutal slavers, commander. Innocents from across Draenor are dragged deep into the volcanic slag mines in Frostfire Ridge to dredge up cart after cart o' gems and ore, never to return.\n\nWe suspect that they have turned their focus to unearthin' an ancient relic o' immense power for their sorcerer-king.\n\nThe ogre Gug'rokk rules over the slag mines with an iron fist. Take him down and the mines will fall as well.", completion = "The Bloodmaul are finished, and with them Imperator Mar'gok's chances of acquiring the relic within the slag mines.\n\nThis is as fine a day as I've seen in some time.", objectives = "Defeat Gug'rokk in the Bloodmaul Slag Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37796] = { id = 37796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun", description = "Commander, Gul'dan's favored agent Teron'gor has infiltrated Auchindoun in Talador and has already taken to devourin' the countless souls within. We mustn't let this nefarious warlock gain any further strength.\n\nEnter the holy mausoleum o' Auchindoun and rout Teron'gor and the rest o' the Shadow Council before more damage is done.", completion = "Well done, commander. Gul'dan will surely tremble at the heels of our victory this day.", objectives = "Defeat Teron'gor in Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37797] = { id = 37797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Cleaver: The First Piece", description = "The journal points to the location of the pieces of Gutrek's Cleaver. It reads:\n\n\"The pommel was brought to the Broken Precipice, where it was to be housed in the skull of Gutrek's first kill. It looks like it was some manner of large beast that he fought in the big bone pit.\"", objectives = "Follow the clue from the journal to find Gutrek's pommel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37798] = { id = 37798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Cleaver: The Second Piece", description = "The search for Gutrek's Cleaver continues. The journal reads:\n\n\"The hilt was to be buried in the marshlands, among the serpents whose poison claimed Gutrek's life. There's something here about covering it with a spiral stone, which is supposed to keep Gutrek's spirit at bay somehow.\"", objectives = "Follow the clue from the journal to find Gutrek's hilt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37799] = { id = 37799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Cleaver: The Final Piece", description = "Only one piece remains. The journal reads:\n\n\"The final piece, Gutrek's blade, was to be displayed in a place of honor for all time overlooking the Ring of Blood. I don't think I've seen it there myself, but it says it's supposed to be somewhere where it has a clear view of every battle.\"", objectives = "Follow the clue from the journal to find Gutrek's blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37800] = { id = 37800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Start the Garrison Campaign" }
quests[37802] = { id = 37802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Hilt Looted" }
quests[37803] = { id = 37803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Pommel Looted" }
quests[37804] = { id = 37804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Blade Looted" }
quests[37805] = { id = 37805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Looted" }
quests[37811] = { id = 37811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Cleaver: The Spirit Forge", description = "With the pieces recovered, all that is left is to reforge Gutrek's Cleaver. Goldspade's journal seems to indicate that the only place to do this is the location where it was initially dismantled.\n\nThe journal mentions a \"Spirit Forge\" used to dismantle the blade, and that it may be located somewhere in the nearby gorge. Find the forge and use it to combine the pieces you've gathered.", progress = "Did you find that old blade Dr. Jones was looking for?", completion = "This matches the description of what Dr. Jones was looking for. I'll make sure it makes it to him. \n\nHere is your reward, {class}.", objectives = "Locate the Spirit Forge in Earthshaker Gorge and reforge Gutrek's Cleaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37813] = { id = 37813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Amethon!", description = "Foreman Grobash in da Talador outpost figures he knows why der's been so much seismic activity recently.\n\nDer be an earth fury called Amethon that be covered in powerful crystals in a cave up above Kuuro's Claim. Da crystals' hummin' be drivin' da fury crazy!\n\nWe want a sample to see if we can figure out why da crystals are so powerful. I wouldn't be askin' ya if I thought anybody else could do it, commander.", progress = "What be makin' that infernal racket? Is that the crystal from Amethon you be holdin'?", completion = "You always be savin' da day, commander. Thank you.", objectives = "Retrieve a Humming Draenite Spike from Amethon above Kuuro's Claim in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37814] = { id = 37814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Gor'thul!", description = "We been hearin' 'bout some real, real bad voodoo in Spires of Arak, commander.\n\nDa Shattered Hand shaman Gor'thul be seen sneakin' about da spires the same time we be hearin' of saberon spirits attackin' our supply caravans and our arakkoa allies.\n\nI think it best if we take no chances. You should deal with da shaman personally before dis matter gets out of hand.", completion = "Da spirits smile upon ya, commander. Thank you for all you do.", objectives = "Slay Gor'thul at Bloodmane Pridelands in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37815] = { id = 37815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Nullifier Darkoor!", description = "Da goblin Gurgthock be requestin' your presence at the Ring of Blood in Nagrand, boss-mon.\n\nIt seems that Mogor, da lord of da ring, be holdin' an exhibition match der and he want you to fight his newest acquisition.\n\nI think it be safe, commander. I heard of dis goblin's work before. If you be ready, whisper to him \"I seek da seeker.\"", completion = "Word already be spreadin' about your exploits. If da ogres did not fear your strength yet, dey should now.", objectives = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37816] = { id = 37816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Undertow!", description = "We be havin' a problem, commander.\n\nWe been sendin' some small boats into the Tanaan Channel north of da Umbrafen in Shadowmoon ta spy on da Alliance base der as well as da Iron Horde in Tanaan Jungle.\n\nDa problem is dat every boat we send out come back in pieces, if it come back at all. We think a water elemental called Undertow is da culprit.\n\nI know you be busy, but destroyin' that creature would be very helpful to our efforts.", progress = "Ey, commander. How you doin' dis fine day?", completion = "A thousand thank yous, commander. Dis spyin' should prove valuable in da comin' months.", objectives = "Kill Undertow in the Tanaan Channel north of Umbrafen in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37817] = { id = 37817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Tremor!", description = "Da Gorgrond outpost be havin' troubles with saberon, and we can't afford ta throw troops at the problem any longer. Don't worry, I be havin' an idea.\n\nThere be an enormous worm beast on the west coast of Gorgrond called Tremor, da devourer of lobstroks. If you killed da beast and brought da pile of lobstrok meat back here, we can cook it 'ere, send it to da outpost, and use it to calm da saberon for good!", progress = "Ey, commander.\n\nWhat be that awful smell?", completion = "Dis be exactly what we need, commander. I'll send it to da chefs right away.", objectives = "Kill Tremor west of Gorgorek's Fall in Gorgrond and obtain the Pile of Partially Digested Lobstrok Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37818] = { id = 37818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Hivelord Ik'rix!", description = "We been tryin' out a new way to temper weapons with ice ravager carapaces. Der icy hides are perfect for da process.\n\nHivelord Ik'rix in da Southwind Cliffs nearby is rumored to be da largest ravager we ever seen - if you could bring its carapace back, we'd be able to make all sorts of things!", progress = "Ey, boss-mon. What can I do for you today?", completion = "Excellent. Dis be exactly what we lookin' for!", objectives = "Retrieve the Iceshatter Carapace from Hiveord Ik'rix at Southwind Cliffs in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37819] = { id = 37819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Darkmoon Races", description = "So this is your first race, eh? Don't worry - it's easier than it looks. Let me break it down for you...\n\nRun through that big  banner there. That starts everything. Then, follow the smaller banners until you see a big, blue Post. Hit that, then return here.\n\nYou're scored on your time, so finish as fast as you can! And watch out for those electrified tripwires. They'll slow you down if you run through them. Good luck!", progress = "Hurry! Hit the blue post!", completion = "You made it! This is just a practice race so your time doesn't matter... other than bragging rights.\n\nTime to try the real race!", objectives = "Run through the Darkmoon Races Start Banner, hit the Blue Post, then return to the Darkmoon Races Start Banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37820] = { id = 37820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatecoil Reinforcements" }
